import "math/big"

func canPartition(nums []int) bool {
    total := 0
    for _, num := range nums {
        total += num
    }
    if total % 2 != 0 {
        return false
    }

    target := total / 2
    dp := big.NewInt(1)

    for _, num := range nums {
        shifted := new(big.Int).Lsh(dp, uint(num))
        dp.Or(dp, shifted)
    }

    return dp.Bit(target) == 1
}
